using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;using DepartmentFinancialRecords.API.Data;
namespace DepartmentFinancialRecords.API.Controllers;
[ApiController][Route("api/auth")]public sealed class AuthController:ControllerBase{private readonly ApplicationDbContext _db;private readonly IConfiguration _config;public AuthController(ApplicationDbContext db,IConfiguration config){_db=db;_config=config;}[HttpPost("login")]public async Task<IActionResult> Login(LoginRequest request){var user=await _db.Users.FirstOrDefaultAsync(x=>x.Username==request.Username);if(user is null||request.Password!="local-development")return Unauthorized();var claims=new[]{new Claim(ClaimTypes.Name,user.Username),new Claim(ClaimTypes.Role,user.Role)};var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_config["Jwt:Key"]??"ReplaceWithSecureKeyForLocalDevelopmentOnly"));var token=new JwtSecurityToken(claims: claims, expires: DateTime.UtcNow.AddHours(8), signingCredentials: new SigningCredentials(key, SecurityAlgorithms.HmacSha256));return Ok(new{token=new JwtSecurityTokenHandler().WriteToken(token),user=user.Username});}public sealed record LoginRequest(string Username,string Password);}
